import re

from moler.cmd.unix.run_script import RunScript


class RunFctCommand(RunScript):
    """Run custom FCT command."""

    __error_command_not_found = re.compile(r"Command\s+not\s+found.")

    def __init__(self, connection, script_command, prompt=None, newline_chars=None, runner=None):
        """
        run_fct_command command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param fct_command: custom FCT command to run.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        """
        super(RunFctCommand, self).__init__(connection=connection, script_command=script_command, prompt=prompt,
                                            newline_chars=newline_chars, runner=runner)
        self.ret_required = True
        self.current_ret["LINES"] = []
        self.error_regex = self.__error_command_not_found

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        self.current_ret["LINES"].append(line)
        return super(RunFctCommand, self).on_new_line(line, is_full_line)


